select case when c.credit_limit >= 12800 then 'high' when c.credit_limit >= 3100 then 'mid' else 'low' end as credit_limit_bucket, max(t.txn_time) as last_txn_time, sum(case when t.merchant = 'Shell' then t.amount else 0 end) as shell_amount from transactions t left outer join accounts a on a.id = t.account_id left outer join customers c on a.customer_id = c.id group by case when c.credit_limit >= 12800 then 'high' when c.credit_limit >= 3100 then 'mid' else 'low' end;
